message.content:
{
  "hypotheses": [
    {
      "team": "home",
      "reasons": [
        {
          "text": "콜롬비아는 페루와의 최근 맞대결 10경기에서 7승을 거두는 등 상대 전적에서 크게 앞선다.",
          "var_ids": ["S02"]
        },
        {
          "text": "이 경기는 단순한 친선전이 아니라 10월 FIFA 데이트를 좋게 마무리할 마지막 기회라 동기부여가 크다.",
          "var_ids": ["R17", "R18"]
        },
        {
          "text": "페루는 올리버 소네가 소집에서 빠지고 마르코 우아만이 오른쪽을 맡게 되어 수비 조직이 재편된다.",
          "var_ids": ["R1", "R2"]
        }
      ],
      "breaks": [
        {
          "text": "로렌소가 선발을 대거 로테이션하고 골키퍼까지 케빈 미에르로 바꾸면 조직력과 후방 연결이 흔들릴 수 있다.",
          "var_ids": ["R10"]
        },
        {
          "text": "콜롬비아는 최근 3경기 무승으로 흐름이 끊겨 있다.",
          "var_ids": ["IR12-home"]
        },
        {
          "text": "주축 선수 한 명이 훈련 후 강한 통증을 호소해 의료진이 긴급 점검을 하는 등 몸 상태 변수가 남아 있다.",
          "var_ids": ["R3"]
        }
      ]
    },
    {
      "team": "away",
      "reasons": [
        {
          "text": "페루는 하이로 벨레스의 돌파와 잔루카 라파둘라의 결정력으로 콜롬비아 수비를 흔들 수 있다.",
          "var_ids": ["R11"]
        },
        {
          "text": "콜롬비아가 선발을 대거 바꾸면 페루가 파고들 틈이 생긴다.",
          "var_ids": ["R10"]
        },
        {
          "text": "콜롬비아도 최근 3경기 무승으로 흐름이 좋지 않아 출발이 흔들릴 여지가 있다.",
          "var_ids": ["IR12-home"]
        }
      ],
      "breaks": [
        {
          "text": "페루는 최근 4경기 무승에 보정 득점이 0.75로 떨어져 결정력이 이어지지 않고 있다.",
          "var_ids": ["IR12-away", "IR04-away"]
        },
        {
          "text": "올리버 소네가 빠진 오른쪽에 마르코 우아만이 들어가면서 측면 수비가 약해질 수 있다.",
          "var_ids": ["R1", "R2"]
        }
      ]
    }
  ],
  "scenarios": [
    {
      "id": "s1",
      "outcomes": [[3, 1], [3, 2]],
      "driver_vars": ["R10", "R17", "R18", "R11"],
      "mechanism": "콜롬비아가 로테이션으로 수비 연결이 느슨해지는 대신, 10월 데이트를 좋게 끝내려는 동기부여로 전방에 인원을 많이 넣는다. 페루도 라파둘라와 벨레스를 앞세워 맞불을 놓아 양쪽 골문이 모두 열린다."
    },
    {
      "id": "s2",
      "outcomes": [[2, 1], [3, 2]],
      "driver_vars": ["R17", "R18", "R10", "IR12-away"],
      "mechanism": "콜롬비아가 강한 동기부여로 전방 압박과 점유를 가져가지만 로테이션된 후방에서 한 번씩 틈이 난다. 페루는 4경기 무승으로 흐름이 끊겨 한 골을 만회하는 데 그친다."
    },
    {
      "id": "s3",
      "outcomes": [[1, 1], [1, 0]],
      "driver_vars": ["R10", "R11", "R3"],
      "mechanism": "콜롬비아의 대거 로테이션과 주축 선수의 몸 상태 변수로 우위가 좁아지고, 페루는 벨레스와 라파둘라의 개인 기량으로 간격을 한 골 안쪽으로 유지한다."
    },
    {
      "id": "s4",
      "outcomes": [[0, 1], [1, 2]],
      "driver_vars": ["IR04-away", "IR12-away", "R11", "R3"],
      "mechanism": "페루는 보정 득점 0.75와 4경기 무승으로 실제보다 낮게 잡히지만, 라파둘라·벨레스의 개인 기량과 콜롬비아의 체력 변수가 겹치면 그 낮은 기대가 뒤집힌다."
    },
    {
      "id": "s5",
      "outcomes": [[1, 0], [2, 0]],
      "driver_vars": ["IR12-home", "IR12-away", "R10", "R1"],
      "mechanism": "양 팀 모두 무승 흐름(콜롬비아 3경기·페루 4경기)에 콜롬비아는 로테이션, 페루는 오른쪽 수비 재편까지 겹쳐 경기가 닫힌다. 한두 번의 마무리로 경기가 갈린다."
    }
  ]
}
